// LampBoard's companion mod: tells the LampBoard panel on this Mac what only
// the session knows — its context as Claude Code counts it, what it has cost,
// the account's rate-limit windows, where it draws and why it ended.
//
// It reads nothing of the conversation unless the person asks it a side question
// from the panel (below) — of a running tool only its name and
// the first line of its shell command or its file path, to say which one a
// stuck session is on; the panel masks what looks like a secret — writes
// nothing, runs nothing, and
// talks to one address: 127.0.0.1, on the port the panel wrote, with the token
// the panel wrote, both under ~/.lampboard.
// When the panel is not there it does nothing, silently: a session must never
// wait on, or hear about, a dashboard. The panel is found from HOME, never from
// LAMPBOARD_HOME, which a project's settings could point anywhere.
//
// One exception, asked for by the person: `/lampmaster <question>` sends the
// question they typed, and the session's folder, to the same address, and
// prints LampMaster's answer (D71).
//
// And one decision, when the person has switched it on in LampBoard: a call
// Claude Code would put to its permission dialog is put to the panel first,
// and the panel's allow or deny stands; unanswered in 55 seconds, or with the
// switch off, the dialog comes as it always did (D80). For that one the mod
// reads a second file the panel wrote, its permission key, sends it to nobody,
// and proves it holds it; the panel's answer counts only signed with it.
//
// And a question Claude asks the person (D86), with the same switch: one
// question, one choice, two to four options, put to the panel first like a
// permission and answered with the option the person picked there; any other,
// or one unanswered in 55 seconds, gets the session's own dialog.
//
// And one question, asked by the person from the panel without disturbing the
// session (D82): a message in this session's box that starts with LampBoard's
// line, proven with that same key, is taken before the session sees it and
// answered with a fork over the conversation — no turn, nothing added to it —
// and only the answer goes to the panel. A message in that shape that is not
// proven is taken all the same and answered by nobody.
//
// And a band above the prompt (D84): what waits for the person in the other
// sessions — their names and one line each, as the panel's queue has them —
// drawn on the screen, never put into the conversation; a digit opens that one
// in the panel. Asked of the panel every few seconds, redrawn only on change.
//
// And the decision board (D105): what the person pinned in LampBoard for this
// session's repository, handed to the model with the next prompt whenever it
// has changed, as context the person does not see — asked with the permission
// key and taken only signed with it, because these words enter the
// conversation. Nothing pinned, or no panel, and the prompt goes as typed.
//
// And the radar (§4.4): before a file is written, the panel is asked whether
// another live session wrote it lately; when one did, an edit the session would
// have made on its own is put to the person first, with a sentence naming that
// session. Asked and taken like the governor; anything else, the edit as it was.
//
// And away (A2): while the person is away, a shell command the engine would run
// on its own and that the panel names destructive is put to them instead, so it
// waits for their return rather than running unseen.
//
// And the governor (G3): a session the person lowered one model in the panel,
// until the window resets, runs on that model — asked at the start of each turn,
// with the permission key, and taken only signed with it. Nothing lowered, no
// panel, or no signature: the session's own model, untouched.
//
// The colours of a row still come from LampBoard's hooks (decision D65); this
// adds only figures. Wire format: version 1 of LampBoardCore/Mod/ModReport.swift.

import { endLamps, registerLamps } from './lamps.js'
import { endLook, registerLook } from './look.js'
import { endInbox, registerInbox } from './inbox.js'

const VERSION = 1

// A permission decides what a session may run, so the panel that answers one
// is found from HOME and never from LAMPBOARD_HOME. A project's settings can set
// LAMPBOARD_HOME — to a folder of its own, with a key and a port of its
// choosing (a security review finding) — and cannot set HOME: measured on the
// test Mac, with a project's settings setting both, the mod read the attacker's
// LAMPBOARD_HOME and the real HOME.
async function realHome($) {
  try {
    const home = await $.env.get('HOME')
    return home && home.startsWith('/') && home !== '/' ? home : null
  } catch (_) {
    return null
  }
}

// A project's own settings can set environment variables for its sessions, so
// a cloned repository could point LAMPBOARD_HOME at itself and ship a port of
// its choosing — and receive every session's reports. So the panel is found
// from HOME alone, which a project's settings cannot set (measured on the test
// Mac); a test runs its sessions with HOME set to its fake home. And the
// address must answer as LampBoard before it is sent anything.
let confirmed = null

async function panel($) {
  try {
    const home = await realHome($)
    if (!home) return null
    const dir = `${home}/.lampboard`
    const token = (await $.fs.read(`${dir}/token`)).trim()
    const port = parseInt((await $.fs.read(`${dir}/port`)).trim(), 10)
    if (!/^[0-9a-f]{16,128}$/.test(token) || !(port >= 1024 && port < 65536)) return null
    const base = `http://127.0.0.1:${port}`
    if (confirmed !== base) {
      const health = await $.http.fetch(`${base}/health`)
      if (!health.ok || health.text.trim() !== 'lampboard') return null
      confirmed = base
    }
    return { base, url: `${base}/mod`, token }
  } catch (_) {
    return null
  }
}

async function post($, kind, fields) {
  try {
    const target = await panel($)
    if (!target) return
    const body = JSON.stringify({ v: VERSION, kind, session: await $.session.id(), ...fields })
    await $.http.fetch(target.url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-LampBoard-Token': target.token },
      body,
    })
  } catch (_) {
    // The panel is closed, restarting or older than this mod: nothing to do.
  }
}

// Whether the session runs on Claude Code's default configuration: then its
// rate-limit windows are those of the account the panel's allowance strip
// shows. Only whether the variable is set is sent, never its value.
async function config($) {
  try { return (await $.env.get('CLAUDE_CONFIG_DIR')) ? 'own' : 'default' } catch (_) { return undefined }
}

// The same allow-list the panel applies to a permission prompt: the first line
// of the shell command or which file, never a tool's free-form input. One line,
// so a heredoc's body never leaves; cut by characters, so no half of a pair.
function detailOf(e) {
  for (const key of ['command', 'file_path', 'notebook_path', 'path']) {
    if (typeof e[key] === 'string' && e[key]) return Array.from(e[key].split('\n')[0]).slice(0, 120).join('')
  }
  return undefined
}

async function model($) {
  try { return await $.session.model() } catch (_) { return undefined }
}

// HMAC-SHA256 by hand: the runtime offers `crypto.subtle.digest` and not the
// keyed functions (measured, 2.1.289). The panel checks and signs with the same.
const hex = (bytes) => Array.from(bytes).map((b) => b.toString(16).padStart(2, '0')).join('')
async function sha256(bytes) {
  return new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))
}
async function hmac(key, message) {
  const encoder = new TextEncoder()
  let k = encoder.encode(key)
  if (k.length > 64) k = await sha256(k)
  const pad = (byte) => Uint8Array.from({ length: 64 }, (_, i) => (k[i] || 0) ^ byte)
  const m = encoder.encode(message)
  const inner = new Uint8Array(64 + m.length)
  inner.set(pad(0x36)); inner.set(m, 64)
  const outer = new Uint8Array(96)
  outer.set(pad(0x5c)); outer.set(await sha256(inner), 64)
  return hex(await sha256(outer))
}

// How many lines an edit or a write touches (D87), counted from the call's own
// input: numbers only leave the session, never the text.
function linesOf(tool, input) {
  // A final newline ends the last line; it does not start another.
  const count = (text) => (typeof text === 'string' && text.length ? text.replace(/\n$/, '').split('\n').length : 0)
  if (tool === 'Edit') return { removed: count(input.old_string), added: count(input.new_string) }
  if (tool === 'MultiEdit' && Array.isArray(input.edits)) {
    return input.edits.reduce((sum, edit) => ({
      removed: sum.removed + count(edit && edit.old_string), added: sum.added + count(edit && edit.new_string),
    }), { removed: 0, added: 0 })
  }
  if (tool === 'Write') return { removed: 0, added: count(input.content) }
  return undefined
}

// Whether a command goes on past the one line the card shows (D87): its
// second line or its 121st character is not read there, so the card says so.
function goesOn(input) {
  const command = typeof input.command === 'string' ? input.command.replace(/\n+$/, '') : ''
  return command.includes('\n') || Array.from(command).length > 120
}

// A question Claude asks (D86): put to the panel only in a shape a card can
// show — one question, one choice, two to four options — proven with the
// permission key like a permission, and answered only with a signed choice.
async function askPanel($, e) {
  try {
    const questions = e.questions || (e.input && e.input.questions) || []
    if (questions.length !== 1) return null
    const q = questions[0]
    const options = Array.isArray(q.options) ? q.options.map((o) => o && o.label) : []
    if (q.multiSelect || (q.kind && q.kind !== 'choice') || options.length < 2 || options.length > 4) return null
    if (!options.every((label) => typeof label === 'string' && label)) return null
    const home = await realHome($)
    if (!home) return null
    const key = (await $.fs.read(`${home}/.lampboard/check-key`)).trim()
    const port = parseInt((await $.fs.read(`${home}/.lampboard/port`)).trim(), 10)
    if (!/^[0-9a-f]{16,128}$/.test(key) || !(port >= 1024 && port < 65536)) return null
    const session = await $.session.id()
    const nonce = crypto.randomUUID()
    const reply = await $.http.fetch(`http://127.0.0.1:${port}/question`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-LampBoard-Nonce': nonce,
        'X-LampBoard-Proof': await hmac(key, `question:${nonce}:${session}:${e.tool_use_id}`),
      },
      body: JSON.stringify({ v: VERSION, session, id: e.tool_use_id, question: q.question, header: q.header, options }),
    })
    const [word, index, signature] = reply.ok ? reply.text.trim().split(' ') : []
    if (word !== 'choose' || !/^[0-3]$/.test(index || '')) return null
    if (!same(signature, await hmac(key, `choose:${nonce}:${index}`))) return null
    const label = options[Number(index)]
    if (label === undefined) return null
    return { result: { questions, answers: { [q.question]: label } } }
  } catch (_) {
    return null
  }
}

// The same comparison whatever the guess: a proof is not found a byte at a time.
function same(a, b) {
  if (typeof a !== 'string' || a.length !== b.length) return false
  let diff = 0
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i)
  return diff === 0
}

// A side question from the panel (D82), as PeerAsk in LampBoardCore writes it.
const ASK = /^LampBoard asks without disturbing \[v1 ([A-Za-z0-9-]{16,64}) ([0-9a-f]{64})\]:\n([\s\S]{1,2000})$/

async function answerQuietly($, nonce, proof, question) {
  try {
    const home = await realHome($)
    if (!home) return
    const key = (await $.fs.read(`${home}/.lampboard/check-key`)).trim()
    if (!/^[0-9a-f]{16,128}$/.test(key)) return
    const session = await $.session.id()
    if (!same(proof, await hmac(key, `fork:${nonce}:${session}:${question}`))) return
    const reply = await $.model.fork({ prompt: question })
    // The first post that carries words of the conversation: the port is asked
    // again whether it is LampBoard, not taken on an earlier answer.
    confirmed = null
    await post($, 'answer', reply.isAnswered ? { id: nonce, text: reply.text } : { id: nonce, reason: reply.reason })
  } catch (_) {
    // The panel waits a minute and says it heard nothing.
  }
}

// The decision board (D105): the version each session was last handed, so a
// board reaches a session once per change and not with every prompt. Recorded
// only once the prompt has entered with it, and forgotten when the session
// compacts or starts again, which can drop what it was handed.
const boards = new Map()
const BOARD_WAIT = 1500

async function boardContext($) {
  try {
    const target = await panel($)
    const home = await realHome($)
    if (!target || !home) return null
    const key = (await $.fs.read(`${home}/.lampboard/check-key`)).trim()
    if (!/^[0-9a-f]{16,128}$/.test(key)) return null
    const session = await $.session.id()
    const nonce = crypto.randomUUID()
    // A prompt never waits long on a dashboard: past this it goes as typed.
    let timer
    const late = new Promise((resolve) => { timer = setTimeout(() => resolve(null), BOARD_WAIT) })
    const reply = await Promise.race([late, $.http.fetch(`${target.base}/mod/decisions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-LampBoard-Token': target.token,
        'X-LampBoard-Nonce': nonce,
        'X-LampBoard-Proof': await hmac(key, `board:${nonce}:${session}`),
      },
      body: JSON.stringify({ v: VERSION, session }),
    })]).finally(() => clearTimeout(timer))
    const cut = reply && reply.ok ? reply.text.indexOf('\n') : -1
    if (cut < 0) return null
    const [word, version, signature] = reply.text.slice(0, cut).split(' ')
    const text = reply.text.slice(cut + 1)
    if (word !== 'board' || !/^([0-9a-f]{16}|-)$/.test(version || '')) return null
    if (!same(signature, await hmac(key, `pinned:${nonce}:${version}:${text}`))) return null
    // Never told and nothing pinned, or told this very version: nothing new.
    if (version === (boards.get(session) || '-')) return null
    return { session, version, text }
  } catch (_) {
    return null
  }
}

// The radar (§4.4): another live session's recent write of this file, in a
// sentence for the person, or nothing.
const WRITERS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])
const RADAR_WAIT = 600

// A question the panel answers with a verdict and, for the one that acts, a
// sentence — signed over both with the permission key (the radar, D113; the
// hold, A2). Nothing, or anything unsigned, is no answer.
async function signedVerdict($, route, tag, subject, fields, acting, wait) {
  try {
    const target = await panel($)
    const home = await realHome($)
    if (!target || !home) return null
    const key = (await $.fs.read(`${home}/.lampboard/check-key`)).trim()
    if (!/^[0-9a-f]{16,128}$/.test(key)) return null
    const session = await $.session.id()
    const nonce = crypto.randomUUID()
    let timer
    // Every call the engine would allow waits on this: shorter than the others.
    const late = new Promise((resolve) => { timer = setTimeout(() => resolve(null), wait) })
    const reply = await Promise.race([late, $.http.fetch(`${target.base}${route}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-LampBoard-Token': target.token,
        'X-LampBoard-Nonce': nonce,
        'X-LampBoard-Proof': await hmac(key, `${tag}:${nonce}:${session}:${subject}`),
      },
      body: JSON.stringify({ v: VERSION, session, ...fields }),
    })]).finally(() => clearTimeout(timer))
    const cut = reply && reply.ok ? reply.text.indexOf('\n') : -1
    const head = reply && reply.ok ? (cut < 0 ? reply.text : reply.text.slice(0, cut)).trim() : ''
    const sentence = cut < 0 ? '' : reply.text.slice(cut + 1)
    const [verdict, signature] = head.split(' ')
    if (verdict !== acting || !sentence) return null
    if (!same(signature, await hmac(key, `${tag}:${nonce}:${verdict}:${sentence}`))) return null
    return Array.from(sentence.replace(/[\u0000-\u001F\u007F-\u009F]/g, ' ')).slice(0, 300).join('')
  } catch (_) {
    return null
  }
}

// The radar (§4.4): another live session's recent write of this file.
const radar = ($, file) => signedVerdict($, '/mod/radar', 'radar', file, { file }, 'written', RADAR_WAIT)

// The hold (A2): away, a destructive command waits for the person. The whole
// command goes, every line — cut at the panel's limit, and said so; only Bash.
const HOLD_LONGEST = 4000
const HOLD_WAIT = 1500
const hold = ($, input) => {
  const whole = Array.from(typeof input.command === 'string' ? input.command : '')
  if (whole.length === 0) return null
  const command = whole.slice(0, HOLD_LONGEST).join('')
  const cut = whole.length > HOLD_LONGEST
  return signedVerdict($, '/mod/hold', 'hold', `${cut ? 1 : 0}:${command}`, { command, cut }, 'hold', HOLD_WAIT)
}

// The governor (G3): the answer each session is waiting for at its turn's start,
// asked before the turn goes on so that its first step already has it.
const governed = new Map()

async function governorModel($) {
  try {
    const target = await panel($)
    const home = await realHome($)
    if (!target || !home) return null
    const key = (await $.fs.read(`${home}/.lampboard/check-key`)).trim()
    if (!/^[0-9a-f]{16,128}$/.test(key)) return null
    const session = await $.session.id()
    const nonce = crypto.randomUUID()
    let timer
    const late = new Promise((resolve) => { timer = setTimeout(() => resolve(null), BOARD_WAIT) })
    const reply = await Promise.race([late, $.http.fetch(`${target.base}/mod/governor`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-LampBoard-Token': target.token,
        'X-LampBoard-Nonce': nonce,
        'X-LampBoard-Proof': await hmac(key, `governor:${nonce}:${session}`),
      },
      body: JSON.stringify({ v: VERSION, session }),
    })]).finally(() => clearTimeout(timer))
    const [word, chosen, signature] = reply && reply.ok ? reply.text.trim().split(' ') : []
    if (word !== 'model' || !/^(claude-[a-z0-9.-]{1,60}|-)$/.test(chosen || '')) return null
    if (!same(signature, await hmac(key, `governed:${nonce}:${chosen}`))) return null
    return chosen === '-' ? null : chosen
  } catch (_) {
    return null
  }
}

// The band (D84): what the panel says waits elsewhere, kept between draws,
// per session — one process can hold several (the Claude app's chats) — with
// one clock each, stopped when that session ends.
const BAND_EVERY = 5000
const bands = new Map()

async function refreshBand($, session) {
  const state = bands.get(session)
  if (!state) return
  let text = '{"items":[],"v":1}'
  try {
    const target = await panel($)
    if (target) {
      const reply = await $.http.fetch(`${target.base}/mod/band`, {
        headers: { 'X-LampBoard-Token': target.token, 'X-LampBoard-Session': session },
      })
      if (reply.ok) text = reply.text
    }
  } catch (_) {
    // The panel is closed or restarting: nothing waits that it can show.
  }
  if (text === state.text) return
  try {
    const read = JSON.parse(text)
    if (read.v !== 1 || !Array.isArray(read.items)) return
    state.text = text
    state.items = read.items
    $.ui.invalidate('ui.render')
  } catch (_) {}
}

async function openInPanel($, session) {
  try {
    const target = await panel($)
    if (!target) return
    await $.http.fetch(`${target.base}/mod/band/open`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-LampBoard-Token': target.token },
      body: JSON.stringify({ session }),
    })
  } catch (_) {}
}

// `/lampmaster <question>` (D71): the person's question to LampMaster, through
// the route the `lampmaster` MCP server uses, so the limits, the daily ceiling
// and the off switch are the same ones. The answer is shown to the person and
// is not handed to the model: it summarises other sessions' work, and what of
// it this session should act on is the person's call. The model has the MCP
// tools for its own questions.
const USAGE = 'Ask LampMaster what your other sessions know: /lampmaster <question>'
// Claude Code empties a box above 10,000 characters; LampBoard's answers stay
// near 2,000.
const MAX_ANSWER = 4000

// The baton (5.4, D91): this session writes what another needs — a fork over
// its own conversation, no turn — and LampBoard puts it in that session's
// composer, unsent. The question is LampBoardCore's Handoff.question, word for word.
const HANDOFF_USAGE = 'Write a handoff for another session: /handoff <session name>'
const HANDOFF_QUESTION = 'Another Claude Code session is taking over from you, or depends on your work. Write the handoff it will read before it starts: what you understood, what you decided and why, what is left to do, and the files you touched. Plain text, at most thirty lines, no secret values.'

async function handOver($, to) {
  if (!(await panel($))) return 'LampBoard is not running on this Mac: there is nowhere to hand over to.'
  try {
    // Proven with the permission key, never the token alone (D80): the token
    // travels with every hook, and would let anyone write in a composer.
    const home = await realHome($)
    const key = home ? (await $.fs.read(`${home}/.lampboard/check-key`)).trim() : ''
    if (!/^[0-9a-f]{16,128}$/.test(key)) return 'LampBoard has no key to prove the handoff with: update the panel.'
    const reply = await $.model.fork({ prompt: HANDOFF_QUESTION })
    if (!reply.isAnswered || !reply.text || !reply.text.trim()) return `No handoff written (${reply.reason || 'no answer'}).`
    // Words of the conversation: the port is asked again whether it is LampBoard.
    confirmed = null
    const target = await panel($)
    if (!target) return 'LampBoard went away while the handoff was written.'
    const text = Array.from(reply.text.trim()).slice(0, MAX_ANSWER).join('')
    const session = await $.session.id()
    const nonce = crypto.randomUUID()
    const answer = await $.http.fetch(`${target.base}/handoff`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-LampBoard-Token': target.token,
        'X-LampBoard-Nonce': nonce,
        'X-LampBoard-Proof': await hmac(key, `handoff:${nonce}:${session}:${to}:${text}`),
      },
      body: JSON.stringify({ v: VERSION, session, to, text }),
    })
    if (!answer.ok) return `LampBoard did not take the handoff (HTTP ${answer.status}).`
    // Shown to the person: no control, no direction-changing character.
    return Array.from(answer.text.trim().replace(/[\u0000-\u0009\u000B-\u001F\u007F-\u009F\u200B-\u200F\u202A-\u202E\u2066-\u2069]/g, ''))
      .slice(0, 400).join('')
  } catch (_) {
    return 'The handoff could not be written.'
  }
}

async function ask($, question) {
  const target = await panel($)
  if (!target) return 'LampBoard is not running on this Mac, so LampMaster cannot answer.'
  try {
    const reply = await $.http.fetch(`${target.base}/lampmaster/tool`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-LampBoard-Token': target.token },
      body: JSON.stringify({
        tool: 'ask_lampmaster',
        arguments: { question },
        session: await $.session.id(),
        cwd: await $.session.cwd(),
      }),
    })
    if (!reply.ok) return `LampBoard did not take the question (HTTP ${reply.status}).`
    const answer = JSON.parse(reply.text)
    if (typeof answer.text !== 'string' || !answer.text.trim()) return 'LampMaster gave no answer.'
    // LampBoard sends it clean already; the mod does not take a terminal's
    // safety on trust from whatever answered on that port. Line breaks stay.
    return Array.from(answer.text.trim().replace(/[\u0000-\u0009\u000B-\u001F\u007F-\u009F]/g, ''))
      .slice(0, MAX_ANSWER).join('')
  } catch (_) {
    return 'LampMaster could not be reached.'
  }
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    try { boards.delete(await $.session.id()) } catch (_) {}
    // One registration each, each on its own: a name another plugin already
    // holds is refused (claude-mem has a `handoff` skill), and in one `try`
    // that refusal took every command after it away (measured, 8 October 2026).
    // Immediate: a question about the other sessions does not depend on this
    // one's turn, and is most useful while that turn is still running.
    try {
      await $.command.register({ name: 'lampmaster', description: 'Ask LampMaster what your other sessions know', argumentHint: '<question>', immediate: true })
    } catch (_) {}
    try {
      await $.command.register({ name: 'handoff', description: 'Write a handoff for another session; it waits in its LampBoard composer', argumentHint: '<session>', immediate: true })
    } catch (_) {}
    try {
      await $.command.register({ name: 'lamps', description: 'Every LampBoard lamp, beside this conversation', immediate: true })
    } catch (_) {}
    await post($, 'start', { surface: e.surface, interactive: e.isInteractive, model: await model($), features: ['ask', 'commands'] })
    // A band only where a person reads it, and one clock per session.
    const session = await $.session.id()
    if (e.isInteractive && !bands.has(session)) {
      bands.set(session, { text: '', items: [], clock: setInterval(() => { void refreshBand($, session) }, BAND_EVERY) })
      void refreshBand($, session)
    }
    return result
  })

  on('session.measure', async ($, e, next) => {
    const result = await next(e)
    await post($, 'measure', {
      model: await model($),
      config: await config($),
      context: { tokens: e.context.tokens, window: e.context.window },
      rateLimits: e.rateLimits.map((r) => ({ kind: r.kind, percentUsed: r.percentUsed, resetsAt: r.resetsAt })),
      cost: e.cost ? { usd: e.cost.usd } : undefined,
    })
    return result
  })

  // Which tool runs, and since when, so the panel can tell a long build from a
  // command left waiting (5.7). The posts are not awaited: a tool call must
  // never wait on the panel, and they cannot throw.
  on('tool.call', async ($, e, next) => {
    // A question answered from the panel never reaches the dialog.
    if (e.tool === 'AskUserQuestion' && e.tool_use_id) {
      const answered = await askPanel($, e)
      if (answered) return answered
    }
    const id = e.tool_use_id
    if (id) void post($, 'tool', { id, tool: e.tool, phase: 'start', detail: detailOf(e) })
    try {
      return await next(e)
    } finally {
      if (id) void post($, 'tool', { id, tool: e.tool, phase: 'end' })
    }
  })

  on('command.run', { command: 'handoff' }, async ($, e) => {
    const to = (e.args || '').trim().replace(/^@/, '')
    if (!to || Array.from(to).length > 80) return { text: HANDOFF_USAGE }
    return { text: await handOver($, to) }
  })

  on('command.run', { command: 'lampmaster' }, async ($, e) => {
    // LampBoard cuts the question to its own limit; this only trims it.
    const question = (e.args || '').trim()
    if (!question) return { text: USAGE }
    // Claude Code prints the plugin's name before the text: no label of our own.
    return { text: await ask($, question) }
  })

  // Only what the engine would ask the person about, and only a real call: the
  // engine's allow and deny are never overturned, and a query is no question.
  // LampBoard answers `ask` at once while its switch is off.
  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    // Away (A2): a destructive command the engine would run on its own waits.
    if (verdict && verdict.decision === 'allow' && e.tool === 'Bash') {
      const said = await hold($, e.input || {})
      if (said) {
        try { void $.ui.toast(`LampBoard · ${said}`, { timeoutMs: 20000 }) } catch (_) {}
        return { decision: 'ask', reason: said }
      }
    }
    // The radar: an edit the session would make on its own, of a file another
    // live session just wrote, is put to the person first.
    if (verdict && verdict.decision === 'allow' && WRITERS.has(e.tool)) {
      const input = e.input || {}
      const file = typeof input.file_path === 'string' ? input.file_path : input.notebook_path
      if (typeof file === 'string' && file.startsWith('/')) {
        const said = await radar($, file)
        if (said) {
          // The edit dialog does not show a hook's reason: the session says it.
          try { void $.ui.toast(`LampBoard · ${said}`, { timeoutMs: 20000 }) } catch (_) {}
          return { decision: 'ask', reason: said }
        }
      }
    }
    if (!verdict || verdict.decision !== 'ask' || !e.tool_use_id) return verdict
    try {
      const home = await realHome($)
      if (!home) return verdict
      // Not the token: every hook and report carries that to whatever answers
      // on the port, which while the panel is away could be anyone's listener.
      const key = (await $.fs.read(`${home}/.lampboard/check-key`)).trim()
      const port = parseInt((await $.fs.read(`${home}/.lampboard/port`)).trim(), 10)
      if (!/^[0-9a-f]{16,128}$/.test(key) || !(port >= 1024 && port < 65536)) return verdict
      const session = await $.session.id()
      const nonce = crypto.randomUUID()
      const reply = await $.http.fetch(`http://127.0.0.1:${port}/check`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-LampBoard-Nonce': nonce,
          'X-LampBoard-Proof': await hmac(key, `ask:${nonce}:${session}:${e.tool_use_id}`),
        },
        body: JSON.stringify({
          v: VERSION, session, id: e.tool_use_id, tool: e.tool, detail: detailOf(e.input || {}),
          lines: linesOf(e.tool, e.input || {}), more: goesOn(e.input || {}),
        }),
      })
      // Only an answer signed with the key counts: a listener without it, on
      // a port the panel left, cannot say allow.
      const [decision, signature] = reply.ok ? reply.text.trim().split(' ') : []
      if (!signature || signature !== (await hmac(key, `answer:${nonce}:${decision}`))) return verdict
      if (decision === 'allow') return { decision: 'allow', reason: 'Allowed from LampBoard.' }
      if (decision === 'deny') return { decision: 'deny', reason: 'Denied from LampBoard.' }
    } catch (_) {
      // The panel is closed or restarting: the dialog, as without it.
    }
    return verdict
  })

  // Taken whether or not it is proven: a message that starts like this is never the
  // session's to read. The answer is not awaited: the delivery is not held.
  on('session.receive', async ($, e, next) => {
    const text = e.text || ''
    if (!text.startsWith('LampBoard asks without disturbing [')) return next(e)
    // Its line, but not its shape (cut, too long): taken all the same.
    const asked = ASK.exec(text)
    if (asked) void answerQuietly($, asked[1], asked[2], asked[3])
    return { consumed: 'lampboard-ask' }
  })

  // The band: nothing while nothing waits elsewhere, so the engine draws its own.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const state = bands.get(await $.session.id())
    const items = state ? state.items.slice(0, 3) : []
    if (items.length === 0 || (e.props && e.props.hasSurvey)) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    // One line whatever the width: each label gets its share of the columns.
    const columns = (e.props && e.props.bodyColumns) || 80
    const share = Math.max(12, Math.floor((columns - 14) / items.length) - 6)
    const fit = (label) => (Array.from(label).length <= share ? label : Array.from(label).slice(0, share - 1).join('') + '…')
    const children = [Text({ color: 'yellow', children: ['⚑ LampBoard · '] })]
    items.forEach((item, i) => {
      children.push(Button({
        key: `band-${i + 1}`, label: fit(`${item.title}: ${item.line}`), hotkey: String(i + 1), plain: true,
        onPress: async () => { await openInPanel($, item.session) },
      }))
      if (i < items.length - 1) children.push(Text({ dimColor: true, children: [' · '] }))
    })
    return Box({ flexDirection: 'row', children })
  })

  // Context on the way down, before the prompt enters: once it has, a block
  // attached is not read (the API's word).
  on('prompt.submit', async ($, e, next) => {
    const board = await boardContext($)
    const block = board && board.text
    const result = await next(block ? { ...e, context: [...(e.context || []), block] } : e)
    if (board && !result.drop) boards.set(board.session, board.version)
    return result
  })

  // The governor (G3): asked once a turn, applied to every step of it.
  on('turn.start', async ($, e, next) => {
    try { governed.set(await $.session.id(), governorModel($)) } catch (_) {}
    return next(e)
  })

  // A streaming event: its hook is an async generator, or it is dropped unseen.
  on('turn.step', async function* ($, e, next) {
    let lowered
    try { lowered = await governed.get(await $.session.id()) } catch (_) {}
    return yield* next(lowered && !e.agentId ? { ...e, model: lowered } : e)
  })

  // A compacted or restarted conversation may have lost what it was handed.
  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    if (!e.agentId) { try { boards.delete(await $.session.id()) } catch (_) {} }
    return result
  })

  // `session.end` has 1.5 s in all: one short post, and no model lookup.
  on('session.end', async ($, e, next) => {
    const result = await next(e)
    const ending = bands.get(e.sessionId)
    if (ending) { clearInterval(ending.clock); bands.delete(e.sessionId) }
    endLamps(e.sessionId)
    endLook(e.sessionId)
    endInbox(e.sessionId)
    boards.delete(e.sessionId)
    governed.delete(e.sessionId)
    await post($, 'end', { session: e.sessionId, reason: e.reason })
    return result
  })

  // The Hub's signed commands (D152), after the governor so the person's choice wins.
  try { registerInbox(on) } catch (_) {}
  // Last, and on its own: a Claude Code without panes must not lose the rest.
  try { registerLamps(on) } catch (_) {}
  // The look (D134), off unless LampBoard says on for the session.
  try { registerLook(on) } catch (_) {}
}

files.hooks/lamps.js:
// The lamps (D131): every session the LampBoard panel on this Mac shows, the
// ones that want something first, in a pane beside the conversation. Opened by
// /lamps and never by itself: a pane that opens unasked takes the width of
// somebody's work. It reads the panel's own `/sessions`, with the panel's token,
// and a row's button raises that session the way a click on its lamp does.
// `/lamps` itself is registered in register.js's `session.start`: the engine
// takes one hook per event, and follows `$` into no imported function.

const PANE = 'lampboard-lamps'
const EVERY = 3000
const WAIT = 2000
const MOST = 30

// The glossary of 1.1 (D128) and the panel's own colours.
const WORDS = { awaiting: 'needs you', failed: 'stopped', ready: 'done', working: 'working', waiting: 'paused', idle: 'resting' }
const COLOR = { awaiting: '#ff7319', failed: '#d93d3d', ready: '#33d96b', working: '#fabf29', waiting: '#6ba8fa', idle: '#9e9e9e' }
const ORDER = { awaiting: 0, failed: 1, ready: 2, working: 3, waiting: 4, idle: 5 }
// The rule the panel holds a session id to (`ModReport.isSessionId`).
const SESSION_ID = /^[A-Za-z0-9-]{8,64}$/

// One state per session: one hooks worker serves every session of the process,
// and a pane, its rows and its clock belong to the session that opened it.
const panes = new Map()

// The panel, found the way register.js finds it, and copied rather than shared:
// Claude Code's check follows `$` only into functions declared in the same file,
// and refuses a module that hands `$` to an imported one. HOME alone, never
// LAMPBOARD_HOME, which a cloned project's settings could point anywhere; and the
// address must answer as LampBoard before it is asked anything.
let confirmedLampBoard = null

// No call to the panel waits longer than this: a stuck panel must not hold a
// command or pile up refreshes.
function bounded(promise) {
  let timer
  const late = new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('late')), WAIT) })
  return Promise.race([promise, late]).finally(() => clearTimeout(timer))
}

async function lampBoard($) {
  try {
    const home = await $.env.get('HOME')
    if (!home || !home.startsWith('/') || home === '/') return null
    const token = (await $.fs.read(`${home}/.lampboard/token`)).trim()
    const port = parseInt((await $.fs.read(`${home}/.lampboard/port`)).trim(), 10)
    if (!/^[0-9a-f]{16,128}$/.test(token) || !(port >= 1024 && port < 65536)) return null
    const base = `http://127.0.0.1:${port}`
    if (confirmedLampBoard !== base) {
      const health = await bounded($.http.fetch(`${base}/health`))
      if (!health.ok || health.text.trim() !== 'lampboard') return null
      confirmedLampBoard = base
    }
    return { base, token }
  } catch (_) {
    return null
  }
}

async function raise($, session) {
  try {
    const target = await lampBoard($)
    if (!target) { $.ui.toast('LampBoard is not answering.'); return }
    const reply = await bounded($.http.fetch(`${target.base}/mod/band/open`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-LampBoard-Token': target.token },
      body: JSON.stringify({ session }),
    }))
    if (!reply.ok) $.ui.toast('LampBoard could not bring that session forward.')
  } catch (_) {
    $.ui.toast('LampBoard is not answering.')
  }
}

// What a session calls itself reaches a terminal: one line, no control, format,
// bidi or invisible characters (a title can come from a cloned repository), cut.
function clean(text) {
  const flat = String(text).replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u206F\uFEFF]|[\u{E0000}-\u{E007F}]/gu, ' ')
  return Array.from(flat).slice(0, 80).join('').trim()
}

async function refresh($, session) {
  const pane = panes.get(session)
  if (!pane || pane.busy) return
  pane.busy = true
  let text = ''
  try {
    const target = await lampBoard($)
    if (target) {
      const reply = await bounded($.http.fetch(`${target.base}/sessions`, { headers: { 'X-LampBoard-Token': target.token } }))
      if (reply.ok) text = reply.text
    }
  } catch (_) {
    text = ''
  } finally {
    pane.busy = false
  }
  if (text === pane.text) return
  pane.text = text
  pane.rows = []
  try {
    const read = text ? JSON.parse(text) : { sessions: [] }
    const seen = new Set()
    pane.rows = (Array.isArray(read.sessions) ? read.sessions : [])
      .filter((s) => s && typeof s.id === 'string' && SESSION_ID.test(s.id) && WORDS[s.status] && !seen.has(s.id) && seen.add(s.id))
      .map((s) => ({ id: s.id, status: s.status, name: clean(s.title || s.workspace || s.id) || s.id }))
      .sort((a, b) => ORDER[a.status] - ORDER[b.status] || a.name.localeCompare(b.name))
      .slice(0, MOST)
  } catch (_) {
    pane.rows = []
  }
  $.ui.invalidate('ui.render')
}

// Called from register.js's `session.end` (which has the id and takes no `$`
// here): a pane's clock does not outlive its session.
export function endLamps(session) {
  const pane = panes.get(session)
  if (pane && pane.clock) clearInterval(pane.clock)
  panes.delete(session)
}

export function registerLamps(on) {
  on('command.run', { command: 'lamps' }, async ($) => {
    const session = await $.session.id()
    try {
      await $.ui.open({ id: PANE, title: 'LampBoard' })
    } catch (_) {
      return { text: 'This layout has no room for a pane: run Claude Code full screen, as a background session always is.' }
    }
    const pane = panes.get(session) || { text: null, rows: [], clock: null, busy: false }
    panes.set(session, pane)
    if (!pane.clock) pane.clock = setInterval(() => { void refresh($, session) }, EVERY)
    void refresh($, session)
    return { text: 'The lamps are beside the conversation.' }
  })

  // Nobody looks at a closed pane: the panel is not asked again until it opens.
  on('ui.close', async ($, e, next) => {
    if (e.id === PANE) {
      try {
        const pane = panes.get(await $.session.id())
        if (pane && pane.clock) { clearInterval(pane.clock); pane.clock = null }
      } catch (_) {}
    }
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const pane = panes.get(await $.session.id())
    if (!pane || pane.text === null) return Text({ dimColor: true, children: ['Asking LampBoard…'] })
    if (pane.rows.length === 0) return Text({ dimColor: true, children: ['No lamps: LampBoard is closed, or quiet.'] })
    const columns = (e.props && e.props.bodyColumns) || 40
    const room = Math.max(1, ((e.viewport && e.viewport.rows) || 24) - 3)
    // The dot, a hotkey's `1: `, a space and the longest word ("needs you").
    const width = Math.max(8, columns - 17)
    const name = (row) => (Array.from(row.name).length <= width ? row.name : Array.from(row.name).slice(0, width - 1).join('') + '…')
    const shown = pane.rows.slice(0, room)
    const children = shown.map((row, i) => Box({
      key: `lamp-${row.id}`,
      flexDirection: 'row',
      children: [
        Text({ color: COLOR[row.status], children: [row.status === 'idle' ? '○ ' : '● '] }),
        Button({
          key: `open-${row.id}`, label: name(row), plain: true,
          ...(i < 9 ? { hotkey: String(i + 1) } : {}),
          onPress: async () => { await raise($, row.id) },
        }),
        Text({ dimColor: true, children: [` ${WORDS[row.status]}`] }),
      ],
    }))
    if (pane.rows.length > shown.length) {
      children.push(Text({ key: 'more', dimColor: true, children: [`+${pane.rows.length - shown.length} more`] }))
    }
    return Box({ flexDirection: 'column', children })
  })
}

files.hooks/look.js:
// The look (D134): inside LampBoard's live view, the transcript drawn as
// close to Claude Code's VS Code panel as a terminal allows. The person's
// prompts sit in rounded boxes; each tool call is one compact row (a status
// dot, the tool, its file or command, + and - counts for an edit); an edit's
// result is a diff in a rounded frame; a todo list is a checklist; the spinner
// says what the turn is doing in one plain word; the hint under the prompt
// ends with the model and how full the context is.
//
// Off unless LampBoard says on, for this session (Settings > Clicks & keys >
// Claude Code's look: in LampBoard's windows, everywhere, or off): the panel on
// this Mac is asked `GET /mod/look` (its token, this session's id) and must
// answer `{"v":1,"on":true}`. The answer is kept five seconds per session. Any
// other answer, no panel, a late one, a surface other than the terminal: the
// engine draws its own, untouched. It reads only what the engine is about to
// draw, sends nothing but the session's id, and writes nothing.
//
// Claude Code's check follows `$` only into functions declared in the same file,
// so the panel lookup is a copy of lamps.js's (HOME only, never LAMPBOARD_HOME;
// the address must answer as LampBoard first). Every hook here has a component
// matcher: the module graph may hold one hook per event without a matcher.

const TTL = 5000
const MISSES = 3
const WAIT = 1500
const SESSION_ID = /^[A-Za-z0-9-]{8,64}$/

// Glyphs, written as escapes: the source holds ASCII only.
const DOT = '\u25CF'
const ELBOW = '\u2514 '
const MINUS = '\u2212'
const ELLIPSIS = '\u2026'
const BOX_EMPTY = '\u2610'
const BOX_DONE = '\u2611'
const ARROW = '\u25B8'
const CROSS = '\u2715'
const MIDDOT = ' \u00B7 '

// How many diff lines a result shows before saying how many it left out.
const DIFF_LINES = 24
const WRITE_LINES = 12

// Tools whose row the look draws; any other keeps the engine's row.
const DRAWN = new Set(['Read', 'Write', 'Edit', 'MultiEdit', 'NotebookEdit', 'Bash', 'Grep', 'Glob', 'LS',
  'WebFetch', 'WebSearch', 'TodoWrite', 'TaskCreate', 'TaskUpdate', 'TaskList', 'Skill', 'ToolSearch'])

// The task tools draw their own checklist line; their result row says nothing more.
const TASKS = new Set(['TodoWrite', 'TaskCreate', 'TaskUpdate', 'TaskList'])

// What the spinner says, by what the turn is doing.
// Whose prompts are boxed: the person's, typed here or through an attach.
const TYPED = new Set(['composer', 'bridge', 'sdk', 'unclassified'])

const DOING = { thinking: 'Thinking', requesting: 'Waiting', responding: 'Writing', 'tool-input': 'Preparing', 'tool-use': 'Working' }

// One state per session: the panel's last answer, when it came, the folder
// paths are shown against, and the tool calls drawn inside an unfolded group.
const looks = new Map()

let confirmedLook = null

function bounded(promise) {
  let timer
  const late = new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('late')), WAIT) })
  return Promise.race([promise, late]).finally(() => clearTimeout(timer))
}

async function lookPanel($) {
  try {
    const home = await $.env.get('HOME')
    if (!home || !home.startsWith('/') || home === '/') return null
    const token = (await $.fs.read(`${home}/.lampboard/token`)).trim()
    const port = parseInt((await $.fs.read(`${home}/.lampboard/port`)).trim(), 10)
    if (!/^[0-9a-f]{16,128}$/.test(token) || !(port >= 1024 && port < 65536)) return null
    const base = `http://127.0.0.1:${port}`
    if (confirmedLook !== base) {
      const health = await bounded($.http.fetch(`${base}/health`))
      if (!health.ok || health.text.trim() !== 'lampboard') return null
      confirmedLook = base
    }
    return { base, token }
  } catch (_) {
    return null
  }
}

async function askLook($, session) {
  try {
    const target = await lookPanel($)
    if (!target) return false
    const reply = await bounded($.http.fetch(`${target.base}/mod/look`, {
      headers: { 'X-LampBoard-Token': target.token, 'X-LampBoard-Session': session },
    }))
    if (!reply.ok) { confirmedLook = null; return null }
    const read = JSON.parse(reply.text)
    return Boolean(read && read.v === 1 && read.on === true)
  } catch (_) {
    confirmedLook = null
    return null
  }
}

// The session's state, the panel asked at most once per TTL. The first ask is
// awaited (bounded); a stale answer is used while a fresh one is fetched, and a
// change redraws every hooked site.
async function lookState($, e) {
  if (!e || e.surface !== 'terminal') return null
  try {
    const session = await $.session.id()
    if (!SESSION_ID.test(session)) return null
    let state = looks.get(session)
    if (!state) {
      state = { on: false, at: 0, misses: 0, pending: null, cwd: '', grouped: new Set(), tasks: new Map() }
      looks.set(session, state)
    }
    if (Date.now() - state.at >= TTL && !state.pending) {
      const first = state.at === 0
      state.pending = (async () => {
        const said = await askLook($, session)
        // No answer (a panel busy for a moment, or gone) keeps the last one,
        // three times at most: a stall must not flicker the look off and on.
        state.misses = said === null ? state.misses + 1 : 0
        const on = said === null ? (state.misses < MISSES && state.on) : said
        if (on && !state.cwd) { try { state.cwd = await $.session.cwd() } catch (_) {} }
        const changed = on !== state.on
        state.on = on
        state.at = Date.now()
        state.pending = null
        // The rows drawn before the first answer are drawn again with it.
        if (changed || (first && on)) { try { $.ui.invalidate('ui.render') } catch (_) {} }
      })()
    }
    // Until the first answer every row waits for it (bounded), not just the
    // one that asked.
    if (state.at === 0 && state.pending) await state.pending
    return state.on ? state : null
  } catch (_) {
    return null
  }
}

// Called from register.js's `session.end`, which has the id and no `$` here.
export function endLook(session) {
  looks.delete(session)
}

// Text that reaches the terminal: no control, bidi or invisible characters;
// tabs and line breaks kept only where asked.
function clean(text, keepLines) {
  const bad = keepLines
    ? /[\u0000-\u0008\u000B-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u206F\uFEFF\u061C\u180E\uFFF9-\uFFFB]|[\u{E0000}-\u{E007F}]/gu
    : /[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u206F\uFEFF\u061C\u180E\uFFF9-\uFFFB]|[\u{E0000}-\u{E007F}]/gu
  return String(text == null ? '' : text).replace(bad, keepLines ? '' : ' ')
}

function cut(text, room) {
  const chars = Array.from(text)
  if (room < 2) return ''
  return chars.length <= room ? text : chars.slice(0, room - 1).join('') + ELLIPSIS
}

// A path cut from its head, so the file's name survives.
function cutPath(text, room) {
  const chars = Array.from(text)
  if (room < 2) return ''
  return chars.length <= room ? text : ELLIPSIS + chars.slice(chars.length - room + 1).join('')
}

function relative(path, cwd) {
  if (typeof path !== 'string') return ''
  if (cwd && path.startsWith(cwd + '/')) return path.slice(cwd.length + 1)
  return path
}

const count = (text) => (typeof text === 'string' && text.length ? text.replace(/\n$/, '').split('\n').length : 0)

// The + and - of an edit: from the stored patch once there, else from the input.
function changesOf(tool, input, output) {
  const patch = output && Array.isArray(output.structuredPatch) ? output.structuredPatch : null
  if (patch && patch.length) {
    let added = 0
    let removed = 0
    for (const hunk of patch) {
      for (const line of hunk.lines || []) {
        if (line.startsWith('+')) added++
        else if (line.startsWith('-')) removed++
      }
    }
    return { added, removed }
  }
  if (tool === 'Edit') return { removed: count(input.old_string), added: count(input.new_string) }
  if (tool === 'MultiEdit' && Array.isArray(input.edits)) {
    return input.edits.reduce((sum, edit) => ({
      removed: sum.removed + count(edit && edit.old_string), added: sum.added + count(edit && edit.new_string),
    }), { removed: 0, added: 0 })
  }
  if (tool === 'Write') return { removed: 0, added: count(input.content) }
  return null
}

// What a row names: the file, the command, the pattern, the address.
function targetOf(tool, input, cwd) {
  const inp = input || {}
  if (typeof inp.file_path === 'string') {
    let text = relative(inp.file_path, cwd)
    if (tool === 'Read' && (inp.offset || inp.limit)) {
      const from = Number(inp.offset) || 1
      text += inp.limit ? `:${from}-${from + Number(inp.limit) - 1}` : `:${from}`
    }
    return { text, isPath: true }
  }
  if (typeof inp.notebook_path === 'string') return { text: relative(inp.notebook_path, cwd), isPath: true }
  if (typeof inp.command === 'string') return { text: inp.command.split('\n')[0], isPath: false }
  if (typeof inp.pattern === 'string') {
    const where = typeof inp.path === 'string' ? `  in ${relative(inp.path, cwd)}` : ''
    return { text: inp.pattern + where, isPath: false }
  }
  if (typeof inp.path === 'string') return { text: relative(inp.path, cwd), isPath: true }
  for (const key of ['url', 'query', 'skill', 'description']) {
    if (typeof inp[key] === 'string') return { text: inp[key], isPath: false }
  }
  return { text: '', isPath: false }
}

// One dim line under a row: what the call came to.
function summaryOf(tool, output) {
  if (output == null) return ''
  if (typeof output === 'string') return output.split('\n')[0]
  if (tool === 'Read' && output.file) {
    const lines = output.file.numLines
    return typeof lines === 'number' ? `${lines} line${lines === 1 ? '' : 's'}` : ''
  }
  if (tool === 'Bash') {
    const out = String(output.stdout || output.stderr || '').replace(/\n+$/, '')
    if (!out) return 'no output'
    const lines = out.split('\n')
    return lines.length === 1 ? lines[0] : `${lines[0]}  (+${lines.length - 1} lines)`
  }
  if (Array.isArray(output.filenames)) return `${output.filenames.length} file${output.filenames.length === 1 ? '' : 's'}`
  if (typeof output.numFiles === 'number') return `${output.numFiles} file${output.numFiles === 1 ? '' : 's'}`
  if (Array.isArray(output.matches)) return `${output.matches.length} match${output.matches.length === 1 ? '' : 'es'}`
  return ''
}

function nameOf(tool) {
  const mcp = /^mcp__([^_]+(?:_[^_]+)*)__(.+)$/.exec(tool)
  return mcp ? `${mcp[1]}${MIDDOT}${mcp[2]}` : tool
}

function dotColor(p) {
  if (p.isInterrupted) return 'warning'
  if (p.isErrored) return 'error'
  if (p.isRunning) return 'subtle'
  return 'success'
}

// The row: a dot, the tool in bold, its target, an edit's counts.
function headerRow(t, p, cwd, columns) {
  const { Box, Text } = t
  const input = p.input || {}
  const name = clean(nameOf(String(p.tool)))
  const changes = changesOf(p.tool, input, p.output)
  const counts = changes ? `  +${changes.added} ${MINUS}${changes.removed}` : ''
  const target = targetOf(p.tool, input, cwd)
  const room = Math.max(8, columns - Array.from(name).length - Array.from(counts).length - 6)
  const shown = target.isPath ? cutPath(clean(target.text), room) : cut(clean(target.text), room)
  const children = [
    Text({ color: dotColor(p), children: [`${DOT} `] }),
    Text({ bold: true, children: [name] }),
  ]
  if (shown) children.push(Text({ color: target.isPath ? 'suggestion' : 'text', children: [`  ${shown}`] }))
  if (changes) {
    children.push(Text({ color: 'success', children: [`  +${changes.added}`] }))
    children.push(Text({ color: 'error', children: [` ${MINUS}${changes.removed}`] }))
  }
  if (p.isInterrupted) children.push(Text({ dimColor: true, children: ['  interrupted'] }))
  return Box({ flexDirection: 'row', children })
}

function summaryRow(t, text, columns) {
  const { Text } = t
  return Text({ dimColor: true, children: [`  ${ELBOW}${cut(clean(text), Math.max(8, columns - 6))}`] })
}

// TodoWrite as a checklist: done, doing, to do.
function todoCard(t, p, columns) {
  const { Box, Text } = t
  const todos = Array.isArray(p.input && p.input.todos) ? p.input.todos : []
  const done = todos.filter((x) => x && x.status === 'completed').length
  const rows = [Box({
    flexDirection: 'row',
    children: [
      Text({ color: dotColor(p), children: [`${DOT} `] }),
      Text({ bold: true, children: ['Todos'] }),
      Text({ dimColor: true, children: [`  ${done}/${todos.length} done`] }),
    ],
  })]
  const room = Math.max(8, columns - 8)
  todos.slice(0, 20).forEach((todo, i) => {
    if (!todo) return
    if (todo.status === 'completed') {
      rows.push(Text({ key: `todo-${i}`, dimColor: true, strikethrough: true, children: [`  ${BOX_DONE} ${cut(clean(todo.content), room)}`] }))
    } else if (todo.status === 'in_progress') {
      rows.push(Text({ key: `todo-${i}`, color: 'claude', bold: true, children: [`  ${ARROW} ${cut(clean(todo.activeForm || todo.content), room)}`] }))
    } else {
      rows.push(Text({ key: `todo-${i}`, children: [`  ${BOX_EMPTY} ${cut(clean(todo.content), room)}`] }))
    }
  })
  if (todos.length > 20) rows.push(Text({ dimColor: true, children: [`  +${todos.length - 20} more`] }))
  return Box({ flexDirection: 'column', children: rows })
}

// One checklist line for a task: done, doing, to do, dropped.
function taskLine(t, key, status, subject, room) {
  const { Text } = t
  const text = cut(clean(subject), room)
  if (status === 'completed') return Text({ key, dimColor: true, strikethrough: true, children: [`${BOX_DONE} ${text}`] })
  if (status === 'in_progress') return Text({ key, color: 'claude', bold: true, children: [`${ARROW} ${text}`] })
  if (status === 'deleted') return Text({ key, dimColor: true, children: [`${CROSS} ${text}`] })
  return Text({ key, children: [`${BOX_EMPTY} ${text}`] })
}

// TaskCreate, TaskUpdate, TaskList: the session's task list as the panel's
// checklist. A task's subject is learnt from its creation's result, drawn
// earlier in the same transcript; an update of one never seen says its number.
function taskCard(t, p, tasks, columns) {
  const { Box, Text } = t
  const input = p.input || {}
  const output = p.output && typeof p.output === 'object' ? p.output : {}
  const room = Math.max(8, columns - 6)
  const dot = Text({ color: dotColor(p), children: [`${DOT} `] })
  if (p.tool === 'TaskCreate') {
    if (output.task && output.task.id) tasks.set(String(output.task.id), { subject: output.task.subject || input.subject, activeForm: input.activeForm })
    return Box({ flexDirection: 'row', children: [dot, taskLine(t, 'task', 'pending', input.subject || '', room)] })
  }
  if (p.tool === 'TaskUpdate') {
    const id = String(input.taskId || '')
    const known = tasks.get(id) || {}
    if (input.subject) tasks.set(id, { ...known, subject: input.subject })
    const subject = input.subject || known.subject || `task ${id}`
    const status = input.status || 'pending'
    const shown = status === 'in_progress' ? (input.activeForm || known.activeForm || subject) : subject
    if (!input.status) return Box({ flexDirection: 'row', children: [dot, Text({ dimColor: true, children: [cut(`updated ${clean(subject)}`, room)] })] })
    return Box({ flexDirection: 'row', children: [dot, taskLine(t, 'task', status, shown, room)] })
  }
  const list = Array.isArray(output.tasks) ? output.tasks : []
  const done = list.filter((x) => x && x.status === 'completed').length
  const rows = [Box({ flexDirection: 'row', children: [dot, Text({ bold: true, children: ['Tasks'] }), Text({ dimColor: true, children: [`  ${done}/${list.length} done`] })] })]
  list.slice(0, 20).forEach((task, i) => {
    if (task) rows.push(Box({ key: `task-${i}`, paddingLeft: 2, children: [taskLine(t, `line-${i}`, task.status, task.subject, room - 2)] }))
  })
  return Box({ flexDirection: 'column', children: rows })
}

// Hunks as a unified diff, cut to `most` lines; a cut hunk gets its header
// counted again from what is kept, so it still parses.
function diffSource(patch, most) {
  const parts = []
  let used = 0
  let left = 0
  for (const hunk of patch) {
    const lines = (hunk.lines || []).map((line) => clean(line, true).replace(/\n/g, ''))
    if (used >= most) { left += lines.length; continue }
    const kept = lines.slice(0, most - used)
    left += lines.length - kept.length
    used += kept.length
    const oldLines = kept.filter((l) => !l.startsWith('+') && !l.startsWith('\\')).length
    const newLines = kept.filter((l) => !l.startsWith('-') && !l.startsWith('\\')).length
    parts.push(`@@ -${hunk.oldStart},${oldLines} +${hunk.newStart},${newLines} @@\n${kept.join('\n')}`)
  }
  return { source: parts.join('\n'), left }
}

function diffCard(t, source, path, left) {
  const { Box, Text, Code } = t
  const children = [Code({ source, format: 'diff', path, wrap: 'truncate-end' })]
  if (left > 0) children.push(Text({ dimColor: true, children: [`${ELLIPSIS} ${left} more line${left === 1 ? '' : 's'}`] }))
  return Box({ flexDirection: 'column', marginLeft: 2, borderStyle: 'round', borderColor: 'subtle', paddingX: 1, children })
}

// An edit's or a write's result: its diff, framed, as the panel draws one.
function editResult(t, tool, output) {
  if (!output || typeof output !== 'object') return null
  const path = typeof output.filePath === 'string' ? output.filePath : undefined
  const patch = Array.isArray(output.structuredPatch) ? output.structuredPatch : []
  if (patch.length) {
    const { source, left } = diffSource(patch, tool === 'Write' ? WRITE_LINES : DIFF_LINES)
    return source ? diffCard(t, source, path, left) : null
  }
  if (tool === 'Write' && typeof output.content === 'string') {
    const lines = output.content.replace(/\n$/, '').split('\n')
    const { source, left } = diffSource([{ oldStart: 0, newStart: 1, lines: lines.map((l) => `+${l}`) }], WRITE_LINES)
    return diffCard(t, source, path, left)
  }
  return null
}

function modelName(model) {
  const bare = String(model || '').replace(/\[.*\]$/, '').replace(/^claude-/, '').replace(/-\d{8}$/, '')
  const m = /^([a-z]+)-(\d+)(?:-(\d+))?$/.exec(bare)
  if (m) return `${m[1][0].toUpperCase()}${m[1].slice(1)} ${m[2]}${m[3] ? '.' + m[3] : ''}`
  return bare ? bare[0].toUpperCase() + bare.slice(1) : ''
}

function seconds(ms) {
  const s = Math.max(0, Math.round(ms / 1000))
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`
}

export function registerLook(on) {
  // The person's prompt in a rounded box, as the panel's bubble; other user
  // rows (notifications, peers) and the ctrl+o transcript keep the engine's.
  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => {
    try {
      const p = e.props || {}
      if (p.isExpanded || (p.origin && !TYPED.has(p.origin.kind)) || p.task || p.from) return next(e)
      const state = await lookState($, e)
      if (!state) return next(e)
      const text = clean(p.text, true).replace(/\s+$/, '')
      if (!text) return next(e)
      const { Box, Text } = $.ui.resolve(e)
      return Box({
        flexDirection: 'row',
        marginTop: 1,
        children: [Box({ borderStyle: 'round', borderColor: 'subtle', paddingX: 1, flexShrink: 1, children: [Text({ children: [text] })] })],
      })
    } catch (_) {
      return next(e)
    }
  })

  // A run of reads and searches unfolds: each call is its own row, as in the
  // panel, and the rows it unfolds into are remembered for their summaries.
  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => {
    try {
      const state = await lookState($, e)
      if (!state) return next(e)
      for (const call of (e.props && e.props.calls) || []) {
        if (call && call.tool_use_id) state.grouped.add(call.tool_use_id)
      }
      if (e.props.isExpanded) return next(e)
      return next({ ...e, props: { ...e.props, isExpanded: true } })
    } catch (_) {
      return next(e)
    }
  })

  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    try {
      const p = e.props || {}
      if (!DRAWN.has(String(p.tool))) return next(e)
      const state = await lookState($, e)
      if (!state) return next(e)
      const t = $.ui.resolve(e)
      const columns = (e.viewport && e.viewport.columns) || 80
      // A standalone row stands a line apart, as the engine's does; the rows of
      // an unfolded group sit together and carry their own result.
      const grouped = state.grouped.has(p.tool_use_id)
      const rows = []
      if (p.tool === 'TodoWrite') rows.push(todoCard(t, p, columns))
      else if (TASKS.has(p.tool)) rows.push(taskCard(t, p, state.tasks, columns))
      else rows.push(headerRow(t, p, state.cwd, columns))
      if (p.isErrored && !p.isInterrupted) {
        // The engine draws an errored call's text inside its own row, and raises
        // no result site for it: the row says it, in the error colour.
        const said = typeof p.output === 'string' ? p.output : summaryOf(p.tool, p.output)
        const lines = clean(said, true).replace(/<\/?tool_use_error>/g, '').trim().split('\n').filter(Boolean)
        lines.slice(0, 3).forEach((line, i) => rows.push(t.Text({
          key: `error-${i}`, color: 'error', children: [`  ${i === 0 ? ELBOW : '  '}${cut(line, Math.max(8, columns - 6))}`],
        })))
      } else if (grouped && !p.isRunning && !TASKS.has(p.tool)) {
        const summary = summaryOf(p.tool, p.output)
        if (summary) rows.push(summaryRow(t, summary, columns))
      }
      return t.Box({ flexDirection: 'column', marginTop: grouped ? 0 : 1, children: rows })
    } catch (_) {
      return next(e)
    }
  })

  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    try {
      const p = e.props || {}
      if (p.isErrored || !DRAWN.has(String(p.tool)) || p.tool === 'Bash') return next(e)
      const state = await lookState($, e)
      if (!state) return next(e)
      const t = $.ui.resolve(e)
      const columns = (e.viewport && e.viewport.columns) || 80
      if (TASKS.has(p.tool)) return t.Box({ flexDirection: 'column', children: [] })
      if (p.tool === 'Edit' || p.tool === 'MultiEdit' || p.tool === 'Write') {
        return editResult(t, p.tool, p.output) || next(e)
      }
      const summary = summaryOf(p.tool, p.output)
      return summary ? summaryRow(t, summary, columns) : next(e)
    } catch (_) {
      return next(e)
    }
  })

  // A calmer spinner: one plain word for what the turn does; the engine keeps
  // its glyph, the elapsed time and the tokens.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    try {
      const p = e.props || {}
      if (p.message) return next(e)
      const state = await lookState($, e)
      if (!state) return next(e)
      return next({ ...e, props: { ...p, word: DOING[p.mode] || 'Working', suffix: ELLIPSIS } })
    } catch (_) {
      return next(e)
    }
  })

  // The line that closes a turn, quiet: how long it took, dim.
  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => {
    try {
      const state = await lookState($, e)
      if (!state) return next(e)
      const { Text } = $.ui.resolve(e)
      return Text({ dimColor: true, children: [`  ${ELBOW}done in ${seconds(e.props.durationMs || 0)}`] })
    } catch (_) {
      return next(e)
    }
  })

  // The panel's footer: the model and the context's fill, after the engine's
  // own hint, whose pills stay live.
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    try {
      const state = await lookState($, e)
      if (!state) return next(e)
      const parts = []
      try { parts.push(modelName(await $.session.model())) } catch (_) {}
      try {
        const usage = await $.session.usage()
        const percent = usage && usage.context ? usage.context.percent : undefined
        if (typeof percent === 'number') parts.push(`${percent}% context`)
      } catch (_) {}
      const tail = parts.filter(Boolean).join(MIDDOT)
      return tail ? next({ ...e, props: { ...e.props, tail } }) : next(e)
    } catch (_) {
      return next(e)
    }
  })
}

